        const got = q.pop();
        if (got !== val) {
          throw new Error(`\npop(): got: ${got}, want: ${val}\n`);
        }
      } else if (cmd === "max") {
        const got = q.max();
        if (got !== val) {
          throw new Error(`\nmax(): got: ${got}, want: ${val}\n`);
        }
      }
    }
  }
