class RunTests {
  public void runTests() {
    Object[][] tests = {
        // Example from the book
        {
            new Object[] { "push", 10 },
            new Object[] { "push", 30 },
            new Object[] { "push", 20 },
            new Object[] { "max", 30 },
            new Object[] { "pop", 10 },
            new Object[] { "max", 30 },
            new Object[] { "pop", 30 },
            new Object[] { "max", 20 },
            new Object[] { "push", 50 },
            new Object[] { "push", 30 },
            new Object[] { "push", 20 },
            new Object[] { "push", 10 },
            new Object[] { "max", 50 },
            new Object[] { "push", 50 },
            new Object[] { "max", 50 },
            new Object[] { "pop", 20 },
            new Object[] { "pop", 50 },
            new Object[] { "max", 50 }
        },
        // Edge cases
        {
            new Object[] { "push", 1 },
            new Object[] { "max", 1 },
            new Object[] { "pop", 1 },
            new Object[] { "push", 2 },
            new Object[] { "max", 2 }
        },
        // Multiple equal values
        {
            new Object[] { "push", 5 },
            new Object[] { "push", 5 },
            new Object[] { "max", 5 },
            new Object[] { "pop", 5 },
            new Object[] { "max", 5 }
        }
    };

    for (Object[] ops : tests) {
      MaxQueue q = new MaxQueue();
      for (Object op : ops) {
        Object[] operation = (Object[]) op;
        String cmd = (String) operation[0];
        int val = (int) operation[1];

        if (cmd.equals("push")) {
          q.push(val);
        } else if (cmd.equals("pop")) {
          int got = q.pop();
          if (got != val) {
            throw new RuntimeException(String.format(
                "\npop(): got: %d, want: %d\n", got, val));
          }
        } else if (cmd.equals("max")) {
          int got = q.max();
          if (got != val) {
            throw new RuntimeException(String.format(
                "\nmax(): got: %d, want: %d\n", got, val));
          }
        }
      }
    }
  }
}

public class Solution {
  public static void main(String[] args) {
    new RunTests().runTests();
  }
}
